};
scwin.inputCalendar2_ondateselect = function(dateStr, dateObj) {
    console.log(dateStr);
};
scwin.getDateCurrent = function(type) {
    var today = new Date();
    var dd = 0;
    var isFirstDay = false;
    if (type == 0) {
        //current date
        dd = today.getDate();
    } else if (type == 1) {
        //next date
        dd = today.getDate() + 1;
    } else {
        //previous date
        if (today.getDate() === 1) {
            isFirstDay = true;
            var date = new Date();
            date.setHours(-1);            
            dd = date.getDate();
        } else {
            dd = today.getDate() - 1;
        }
    }
    var mm = isFirstDay ? today.getMonth() : today.getMonth() + 1;
    var yyyy = today.getFullYear();
    if (dd < 10) {
        dd = '0' + dd
    }
    if (mm < 10) {
        mm = '0' + mm
    }
    today = yyyy + "-" + mm + "-" + dd;
    return today;
}
scwin.__ispreviousElement = function() {
    var id = $('td.w2calendar_selected').last().attr("id");
    var el = scwin.__getDom($p.id + id).previousSibling;
    return el;
}
scwin.__isnextElement = function() {
    var id = $('td.w2calendar_selected').last().attr("id");
    var el = scwin.__getDom($p.id + id).nextSibling;
    return el;
}
scwin.checkVal0 = function() {
    return scwin.__getObj('inputCalendar1_calendar_currentDate').innerText == scwin.getDateCurrent(0);
}
scwin.checkVal1 = function() {
    return scwin.getDateCurrent(0) === scwin.__getObj('inputCalendar1_calendar_currentDate').innerText;
}
scwin.checkVal2 = function() {
    return scwin.getDateCurrent(1) === scwin.__getObj('inputCalendar1_calendar_currentDate').innerText;
}
scwin.checkVal3 = function() {
    return scwin.getDateCurrent(0) === scwin.__getObj('inputCalendar2_calendar_currentDate').innerText;
}
scwin.checkVal4 = function() {
    return scwin.getDateCurrent(2) === scwin.__getObj('inputCalendar2_calendar_currentDate').innerText;
}
